<section class="panel"><div class="section-heading"><div><h2>Your credentials</h2><p>Replace or revoke access when an integration changes.</p></div><span class="pill">{{ $credentials->total() }} credentials</span></div>@if($credentials->isEmpty())<div class="empty-state"><h3>No credentials yet</h3><p>Create a scoped credential above to connect your first integration.</p></div>@else<div class="table-scroll"><table><thead><tr><th>Name and permissions</th><th>Expires UTC</th><th>Last used UTC</th><th>Actions</th></tr></thead><tbody>@foreach($credentials as $key)<tr><td><strong>{{ $key->name }}</strong><small>{{ implode(', ',json_decode($key->scopes,true)) }}</small></td><td>{{ $key->expires_at }}</td><td>{{ $key->last_used_at ?? 'Never' }}</td><td>@if($key->revoked_at)<span class="pill">Revoked</span>@elseif(now()->gte($key->expires_at))<span class="pill">Expired</span>@else<form class="inline-form" method="post" action="{{ route('client.integrations.credential',$key->id) }}">@csrf<button class="button secondary" name="action" value="rotate">Replace</button><button class="button danger" name="action" value="revoke">Revoke</button></form>@endif</td></tr>@endforeach</tbody></table></div>{{ $credentials->links('clients.pagination') }}@endif<p class="help-text" style="margin-top:16px">Replacement immediately revokes the old credential. Secrets cannot be displayed again.</p></section>
