<section class="panel"><div class="section-heading"><div><h2>Your webhooks</h2><p>Manage endpoint access and signing secrets.</p></div><span class="pill">{{ $subscriptions->total() }} subscriptions</span></div>@if($subscriptions->isEmpty())<div class="empty-state"><h3>No webhooks configured</h3><p>Add an endpoint above to receive account events.</p></div>@else<ul class="resource-list">@foreach($subscriptions as $s)<li><p style="overflow-wrap:anywhere"><strong>{{ $s->url }}</strong> <span class="pill {{ $s->active?'good':'' }}">{{ $s->active?'Active':'Disabled' }}</span></p><p class="help-text">{{ implode(', ',json_decode($s->events,true)) }}</p>@if($s->active)<form class="inline-form" method="post" action="{{ route('client.integrations.subscription',$s->id) }}">@csrf<button class="button secondary" name="action" value="rotate">Replace signing secret</button><button class="button danger" name="action" value="disable">Disable webhook</button></form>@endif</li>@endforeach</ul>{{ $subscriptions->links('clients.pagination') }}@endif<p class="help-text" style="margin-top:16px">A new signing secret applies to future sends and pending retries. An in-flight send may use the previous secret.</p></section>
<section class="panel"><div class="section-heading"><div><h2>Delivery history</h2><p>Retries stop after five attempts or seven days. Reconcile unknown sends with your receiver before retrying.</p></div></div>@if($deliveries->isEmpty())<div class="empty-state"><h3>No deliveries yet</h3><p>Delivery status and retry history will appear here when events are sent.</p></div>@else<div class="table-scroll"><table><thead><tr><th>Delivery ID</th><th>Status</th><th>Attempts</th><th>HTTP</th><th>Details</th></tr></thead><tbody>@foreach($deliveries as $d)<tr><td>{{ $d->uuid }}</td><td><span class="pill">{{ ucfirst($d->status) }}</span></td><td>{{ $d->attempts }}</td><td>{{ $d->http_status }}</td><td>{{ $d->failure_reason }}@if(in_array($d->status,['unknown','failed'])&&$d->attempts<5&&!$d->redacted_at&&now()->subDays(7)->lte($d->created_at))<form method="post" action="{{ route('client.integrations.retry',$d->id) }}">@csrf<label><input type="checkbox" name="confirm" value="1" required><span>I reconciled with the receiver and accept a possible duplicate.</span></label><button class="button secondary">Request retry</button></form>@endif</td></tr>@endforeach</tbody></table></div>{{ $deliveries->links('clients.pagination') }}@endif</section>
